using Assets.Scripts.UI.TitleScreen;
using UnityEngine;
using UnityEngine.UI;

namespace Assets.Scripts.UI.ConfigWindow
{
    //Rows are generated by OptionList from GameConfig.TitleScreenLayout.
    public class TitleScreenMiniOptionsWindow : WindowBase
    {
        public LoginBox LoginBox;
        public Button OptionsButton;

        public void Awake()
        {
            OptionsButton.interactable = false;
        }

        public override void HideWindow()
        {
            OptionsButton.interactable = true;
            //a click into the login box focuses the field it landed on
            if(LoginBox.gameObject.activeInHierarchy && !RectTransformUtility.RectangleContainsScreenPoint((RectTransform)LoginBox.transform, Input.mousePosition))
                LoginBox.ReturnFocus();
            base.HideWindow();
        }

        public void Update()
        {
            if (Input.GetKeyDown(KeyCode.Escape) || (Input.GetMouseButtonUp(0) && !IsPointerOverUIObject()))
                HideWindow();
        }
    }
}